__global__ void layer_norm(const float* input, const float* gamma, const float* beta, float* output, int n) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= n) {
    return;
  }
  int row = i / 4;
  int col = i % 4;
  float mean = 0.0f;
  for (int j = 0; j < 4; j++) {
    mean += input[row * 4 + j];
  }
  mean = mean / 4.0f;
  float variance = 0.0f;
  for (int j = 0; j < 4; j++) {
    float delta = input[row * 4 + j] - mean;
    variance += delta * delta;
  }
  variance = variance / 4.0f;
  float normalized = (input[i] - mean) / sqrtf(variance + 0.00001f);
  output[i] = normalized * gamma[col] + beta[col];
}
